DECLARE
    v_unique NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_unique FROM jvm_schema u WHERE u.label = 'Session' AND u.properties = '["lastActivityAt","sessionId"]' AND u.kind = 'UNIQUENESS_CONSTRAINT' AND JSON_VALUE(u.properties, '$.size()' RETURNING NUMBER) = 1 AND EXISTS (SELECT 1 FROM user_indexes q WHERE q.index_name = UPPER(u.object_name));
    IF v_unique = 0 THEN
        EXECUTE IMMEDIATE 'CREATE INDEX IF NOT EXISTS jvm_lx_SessionlastActivityAtsessionId_396a2573 ON jvm_node n (CASE WHEN JSON_EXISTS(n.labels, ''$[*]?(@ == "Session")'') THEN JSON_VALUE(n.props, ''$.lastActivityAt'') END, CASE WHEN JSON_EXISTS(n.labels, ''$[*]?(@ == "Session")'') THEN JSON_VALUE(n.props, ''$.sessionId'') END)';
    END IF;
END;

