BEGIN EXECUTE IMMEDIATE 'CREATE OR REPLACE TRIGGER jvm_v_Chunkembedding_7e60bd64_t AFTER INSERT OR UPDATE OF labels, props ON jvm_node FOR EACH ROW
BEGIN
    IF INSTR(JSON_SERIALIZE(:NEW.labels), ''"Chunk"'') > 0 AND JSON_EXISTS(:NEW.props, ''$.embedding'') THEN
                BEGIN
            MERGE INTO jvm_v_Chunkembedding_7e60bd64 s USING (SELECT :NEW.nid AS nid, TO_VECTOR(JSON_QUERY(:NEW.props, ''$.embedding'' RETURNING CLOB)) AS embedding FROM dual) n ON (s.nid = n.nid)
WHEN MATCHED THEN UPDATE SET s.embedding = n.embedding
WHEN NOT MATCHED THEN INSERT (nid, embedding) VALUES (n.nid, n.embedding);
        EXCEPTION WHEN OTHERS THEN
            -- Not a payload the column takes: the node is kept, and left out of the table, as the graph engines leave it out of the index.
            DELETE FROM jvm_v_Chunkembedding_7e60bd64 WHERE nid = :NEW.nid;
        END;
    ELSE
        DELETE FROM jvm_v_Chunkembedding_7e60bd64 WHERE nid = :NEW.nid;
    END IF;
END;'; END;

